def _update_colocation_relationships(self):
    active_agents = self.agents.get_active_agents()
    processed = set()

    for agent in active_agents:
        nearby = self._previous_nearby.get(agent.id, set())
        for other_id in nearby:
            pair = tuple(sorted([agent.id, other_id]))
            if pair in processed:
                continue
            processed.add(pair)

            count = self.relationships.track_colocation(agent.id, other_id)
            if count > 0 and count % 5 == 0:
                events = self.relationships.update_score(
                    self.agents.agents, agent.id, other_id, 1
                )
                for ev in events:
                    if ev.data.get("with_id") == other_id:
                        self.events.push(agent.id, ev)
                    else:
                        self.events.push(other_id, ev)

