    from world.world_events import pick_random_world_event
    we = pick_random_world_event()
    event = WorldEvent(
        type="world_event",
        data={
            "category": we["category"],
            "description": we["description"],
        }
    )
    for agent in self.agents.get_active_agents():
        self.events.push(agent.id, event)
    self._add_recent_event("world_event", f"[{we['category'].upper()}] {we['description']}")
    # Log to DB
    try:
        from django.db import close_old_connections
        from world.models import WorldLog
        close_old_connections()
        WorldLog.objects.create(event_type="world_event", data_json=json.dumps(we))
    except Exception as e:
        logger.error(f"WorldLog save error: {e}")

