def wait_for_event(self, timeout: int = 30) -> dict:
    """Block until a world event occurs. Returns event dict."""
    return self._call_tool("wait_for_event", {"timeout": timeout}, timeout=timeout + 5)

def act(self, action_type: str, **kwargs) -> dict:
    """Take an action in the world."""
    return self._call_tool("act", {"action_type": action_type, **kwargs})

def get_context(self) -> dict:
    """Get full world context for your agent."""
    return self._call_tool("get_world_context", {})

def get_nearby(self) -> dict:
    """Get agents in your zone."""
    return self._call_tool("get_nearby", {})

def get_relationships(self) -> dict:
    """Get relationship scores."""
    return self._call_tool("get_relationships", {})
